require "date"
require "json"
require "time"

module Booking
  module Adapters
    # Padel Gldani is a React app over tRPC (v11, superjson) at its own
    # `/api/trpc`, generated by the Manus app builder. Its booking page reads
    # with plain GETs — no login, no cookie, no token — and so do we: the court
    # list, then the booked intervals of all three courts for one date, batched
    # into one request the way tRPC's own client batches them.
    #
    # The site's robots.txt has said `Disallow: /api/` since 2026-09-30,
    # probably the Manus platform's default rather than the club's choice. We
    # read it anyway, at the same low rate as every club, because it is the
    # public availability every visitor's browser loads — the reasoning is
    # docs/adr/0004. A login or a captcha in front of it would end that.
    #
    # The source reports what is *taken*, as `startTime`–`endTime` intervals,
    # so the free hours are the club's day minus those. Which rows make up a
    # day is the site's own rule (`Zde` in its bundle), and it is not
    # `bookingDate`: a business day is its date's rows starting at 08:00 or
    # later, plus the *next* date's rows starting before 08:00. Asked for
    # 2026-10-14 on 2026-10-13, court 1 answered with a 00:00 row dated the
    # 13th and court 2 with a 00:00 row dated the 14th — both the 14th's
    # calendar midnight, both the 13th's night, and only that rule files them
    # both there. So a day needs its own date's answer and the next one's;
    # each date is asked about once per tick.
    class Padelgldani
      BASE_URL = "https://padelgldani.ge/api/trpc".freeze
      PROCEDURE = "bookings.getBookedSlots".freeze
      # The site's date chips: fourteen, counting today. Past them nobody can
      # book, so everything would read free and never change.
      DEFAULT_MAX_DAYS = 14
      # Where the site's day turns over: a start before 08:00 belongs to the
      # night before (its `pa` helper counts it as hour + 24).
      DAY_STARTS = 8 * 60
      HOUR = 3600
      BOOKABLE = "available".freeze

      def initialize(club, http:, clock: Clock)
        @club = club
        @http = http
        @clock = clock
        @base_url = club.settings.fetch("base_url", BASE_URL)
        @max_days = Integer(club.settings.fetch("max_days", DEFAULT_MAX_DAYS))
        @booking_url = club.settings.fetch("booking_url")
      end

      def fetch(date_range)
        now = @clock.now
        courts = bookable_courts
        booked = Hash.new { |cache, date| cache[date] = booked_on(date, courts) }

        date_range.to_a.first(@max_days)
                  .flat_map { |date| courts.flat_map { court_slots(_1, date, booked, now) } }
                  .uniq(&:key)
      end

      private

      # Read every tick, for its `status` more than its names: a court under
      # maintenance still answers with nothing booked, and inverted that is a
      # whole day freeing up. The site won't sell it, so neither do we.
      def bookable_courts
        # superjson's spelling of "no input".
        rows = batch("courts.list", [{ "json" => nil, "meta" => { "values" => ["undefined"] } }]).first
        raise SourceUnavailable, "courts.list: expected a list of courts, got #{rows.inspect[0, 200]}" unless rows.is_a?(Array)

        courts = rows.select { _1["status"] == BOOKABLE }
        # No courts means no grid to subtract from, and an empty fetch after a
        # full one reads as the whole club booking up at once.
        raise SourceUnavailable, "courts.list: no bookable courts in #{rows.inspect[0, 200]}" if courts.empty?

        courts
      end

      # Every court on one date, in one request.
      def booked_on(date, courts)
        answers = batch(PROCEDURE, courts.map { { "json" => { "courtId" => _1.fetch("id"), "date" => date.to_s } } })

        courts.zip(answers).to_h do |court, rows|
          # Inverted, an error body would read as a court with nothing booked —
          # a whole day freeing up at once.
          raise SourceUnavailable, "#{PROCEDURE}: expected a list of bookings for court #{court["id"]} on #{date}, got #{rows.inspect[0, 200]}" unless rows.is_a?(Array)

          [court.fetch("id"), rows]
        end
      end

      # tRPC's batch shape: the procedure named once per call in the path,
      # inputs keyed by position, and one `{"result":{"data":{"json":…}}}` back
      # per call in the same order — or an `{"error":…}` in a call's place.
      def batch(procedure, inputs)
        url = "#{@base_url}/#{([procedure] * inputs.size).join(",")}"
        input = inputs.each_with_index.to_h { |each, i| [i.to_s, each] }
        payload = @http.get_json(url, { "batch" => 1, "input" => JSON.generate(input) })

        unless payload.is_a?(Array) && payload.size == inputs.size && payload.all? { _1.is_a?(Hash) && _1.dig("result", "data")&.key?("json") }
          raise SourceUnavailable, "#{url}: expected #{inputs.size} tRPC results, got #{payload.inspect[0, 200]}"
        end

        payload.map { _1.dig("result", "data", "json") }
      end

      def court_slots(court, date, booked, now)
        id = court.fetch("id")
        taken = booked[date].fetch(id).select { minutes(_1["startTime"]) >= DAY_STARTS } +
                booked[date + 1].fetch(id).select { minutes(_1["startTime"]) < DAY_STARTS }

        @club.opening_hours.starts_by_label(date).filter_map do |label, starts_at|
          # Inverting a booked list hands back the hours already gone too; the
          # site greys them out, and so must we.
          slot(court, starts_at) unless starts_at <= now || taken.any? { covers?(_1, label) }
        end
      end

      # The site's own test. A payment hold or a pending booking counts: the
      # site exempts only the visitor's own hold, and we never hold one.
      def covers?(booking, label)
        start = night_minutes(label)
        start >= night_minutes(booking["startTime"]) && start < night_minutes(booking["endTime"])
      end

      def minutes(time)
        hour, minute = time.to_s.split(":").map(&:to_i)
        (hour.to_i * 60) + minute.to_i
      end

      # 00:00 to 07:59 counted past 24:00, so 23:00–02:00 is one span.
      def night_minutes(time)
        value = minutes(time)
        value < DAY_STARTS ? value + (24 * 60) : value
      end

      def slot(court, starts_at)
        id = court.fetch("id")

        Slot.new(
          club_slug: @club.slug,
          court_ref: @club.canonical_court(id),
          # "Croco Court I - გადახურული": the part after the dash is the cover,
          # in Georgian, which the club's Profile already says in English.
          court_label: court["name"].to_s.split(" - ").first.to_s.strip.then { _1.empty? ? "Court #{id}" : _1 },
          starts_at:,
          ends_at: starts_at + HOUR,
          price: @club.settings["price"],
          # The one deeplink here that names a court: the booking page reads
          # `?court=` and opens on that court's date picker. No date or hour.
          deeplink: "#{@booking_url}?court=#{id}"
        )
      end
    end
  end
end
